// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _am) public {
        // Restrict _val to a reasonable bound to avoid overflow in balances addition
        _val = bound(_val, 0, 1e30);
        // Restrict _am to a reasonable bound
        _am = bound(_am, 0, 1e30);
        // Set MinSum via the public function (only possible before initialization)
        c.SetMinSum(_val);
        // Initialize to lock MinSum
        c.Initialized();
        // Record MinSum before Collect
        uint before = c.MinSum();
        // Give this contract some ether so Deposit can work
        vm.deal(address(this), 1e30);
        // Deposit some amount so balance is sufficient for Collect
        (bool depOk, ) = address(c).call{value: _am}('');
        // Skip if deposit reverted (should not happen with bounded values)
        if (!depOk) return;
        // Now call Collect with _am
        (bool collectOk, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        // If Collect reverted, we cannot assert on state changes; skip
        if (!collectOk) return;
        // Assert that MinSum remained unchanged
        assertTrue(c.MinSum() == before);
    }
}

